  "app-bridge.d.ts": "import type { ArtifactObservation, DossierContext, DossierState, ModelTrace, ModuleValues } from './protocol';\ntype ModuleListener = (values: ModuleValues) => void;\ntype ActionListener = (payload: unknown) => void;\ntype DossierListener = (state: DossierState) => void;\ndeclare const theorem: {\n    /**\n     * The page's one conversation. A question asked here goes to the page's\n     * agent with this App's revision and the `context` given, and its reply is\n     * in the conversation like any other; `watch` follows the questions asked\n     * from this App and their replies.\n     */\n    dossier: {\n        ask: (text: string, context?: DossierContext) => Promise<void>;\n        /** Calls `listener` with the App's part of the conversation, and again when it changes. */\n        watch(listener: DossierListener): () => void;\n        /** Opens this App's source where `name` is written, for the person to read. */\n        source: (name: string) => Promise<boolean>;\n    };\n    /**\n     * A model's run, cycle by cycle, written as a Rerun recording by Rerun's\n     * own SDK: `.rrd` bytes for `LogChannel.send_rrd` in Rerun's web viewer.\n     */\n    trace: {\n        recording: (trace: ModelTrace) => Promise<Uint8Array<ArrayBufferLike>>;\n    };\n    /**\n     * Keeps runs and results beyond this open App, for this person: a question\n     * about a moment or a result can then be resolved exactly from another\n     * conversation or App. Each is written once; writing it again is a no-op.\n     */\n    artifacts: {\n        /**\n         * Records a run's next observations (`@theorem/runtime`'s RunRef, then\n         * observations continuing from index 0 with no gaps). A run that names no\n         * source is recorded as run by this App's revision.\n         */\n        record: (run: object, domain: string, observations: Array<ArtifactObservation>) => Promise<{\n            through: string | null;\n            source: unknown;\n        }>;\n        /** Keeps a result (a ResultRef whose `content` is the digest of `bytes`) with its bytes. */\n        result: (result: object, bytes: Uint8Array) => Promise<{\n            id: string;\n        }>;\n        /** Whether a subject is held exactly; never answered with the latest instead. */\n        resolve: (subject: object) => Promise<import(\"./protocol\").ArtifactResolution>;\n    };\n    /** Resolves once the page has connected this app. */\n    ready: Promise<undefined>;\n    files: {\n        text: (path: string) => Promise<string>;\n        json: (path: string) => Promise<unknown>;\n        csv: (path: string) => Promise<Array<Record<string, unknown>>>;\n        bytes: (path: string) => Promise<Uint8Array>;\n        list: (glob: string) => Promise<import(\"./protocol\").ListedFile[]>;\n        write: (path: string, text: string) => Promise<{\n            hash: string;\n        }>;\n    };\n    state: (name: string) => Promise<import(\"./cell\").Collection>;\n    /** A graph database kept in this browser, declared with `db(\"name\")`. */\n    db: (name: string) => Promise<{\n        name: string;\n        inspect: () => Promise<{\n            writable: boolean;\n            version: number;\n            nodes: number;\n            edges: number;\n            history: {\n                commits: number;\n                oldestMs: number;\n            } | null;\n            historyDays: number;\n        }>;\n        mutate: (batch: import(\"./db\").DbBatch) => Promise<{\n            txnId: number;\n            graphVersion: number;\n        }>;\n        getNode: (id: string) => Promise<import(\"./db\").DbNode | null>;\n        getEdge: (id: string) => Promise<import(\"./db\").DbEdge | null>;\n        queryNodes: (filter?: import(\"./db\").DbNodeFilter) => Promise<Array<import(\"./db\").DbNode>>;\n        neighbors: (filter: import(\"./db\").DbNeighborFilter) => Promise<Array<import(\"./db\").DbNeighbor>>;\n        query: (cypher: string, params?: Record<string, unknown>, rowCap?: number) => Promise<import(\"./db\").DbQueryResult>;\n        subscribe: <TValue = unknown>(read: import(\"./db\").DbSubscription, next: (value: TValue) => void, error?: ((error: import(\"./db\").DbError) => void) | undefined) => () => void;\n    }>;\n    run: (target: string) => Promise<import(\"./protocol\").RunRequestResult>;\n    module: {\n        /** Calls `listener` with the current values, and again when they change. */\n        onInputs(listener: ModuleListener): () => void;\n        /** Calls `listener` each time a route reaches the declared action `name`. */\n        onAction(name: string, listener: ActionListener): () => void;\n        output: (name: string, value: unknown) => Promise<null>;\n        emit: (name: string, payload: unknown) => Promise<null>;\n    };\n};\n/**\n * What an App reaches as `window.theorem`. The checker's declarations for it\n * are written from this type (scripts/app-declarations.ts), so what an App is\n * checked against is what it is given.\n */\nexport type TheoremApp = typeof theorem;\nexport {};\n",
  "cell.d.ts": "import type { Rpc, RunOutcome } from './protocol';\n/** A compiled cell module, as compile.ts writes it. */\nexport interface CellModule {\n    default: (...args: Array<unknown>) => unknown;\n    inputs: Array<string>;\n    outputs: Array<string>;\n    autodisplay: boolean;\n}\n/** Where a cell's displayed values go. */\nexport interface Display {\n    show: (value: unknown) => void;\n    clear: () => void;\n}\ntype Listener = () => void;\n/** A named shared-state collection: a map of keys to values, kept by the page. */\nexport declare class Collection {\n    readonly name: string;\n    private readonly rpc;\n    private value;\n    private readonly listeners;\n    constructor(name: string, rpc: Rpc, initial: Record<string, unknown>);\n    get: (key: string) => unknown;\n    has: (key: string) => boolean;\n    keys: () => Array<string>;\n    entries: () => Array<[string, unknown]>;\n    /** The whole collection. It is a new object after every change. */\n    snapshot: () => Record<string, unknown>;\n    toJSON: () => Record<string, unknown>;\n    set: (key: string, value: unknown) => Promise<void>;\n    delete: (key: string) => Promise<void>;\n    subscribe: (listener: Listener) => (() => void);\n    /** The collection as a React hook: re-renders on every change. */\n    use: () => Record<string, unknown>;\n    /** The page's copy changed. */\n    replace(value: Record<string, unknown>): void;\n}\n/** The state of a sandbox document: its collections, kept across runs. */\nexport declare class CellContext {\n    readonly rpc: Rpc;\n    readonly display: Display;\n    readonly collections: Map<string, Promise<Collection>>;\n    private disposeRun;\n    private runId;\n    constructor(rpc: Rpc, display: Display);\n    state: (name: string) => Promise<Collection>;\n    /** The page's copy of a collection changed. */\n    changed(name: string, value: Record<string, unknown>): Promise<void>;\n    /** The `files` builtin: reads and writes the page checks against the declarations. */\n    files(): {\n        text: (path: string) => Promise<string>;\n        json: (path: string) => Promise<unknown>;\n        csv: (path: string) => Promise<Array<Record<string, unknown>>>;\n        bytes: (path: string) => Promise<Uint8Array>;\n        list: (glob: string) => Promise<import(\"./protocol\").ListedFile[]>;\n        write: (path: string, text: string) => Promise<{\n            hash: string;\n        }>;\n    };\n    /** Runs the cell once with the other blocks' values it reads. */\n    run(module: CellModule, inputs: Record<string, unknown>): Promise<RunOutcome>;\n}\nexport {};\n",
