  "db.d.ts": "import type { DbFailure, DbOutcome, Rpc } from './protocol';\nexport interface DbNode {\n    id: string;\n    labels: Array<string>;\n    properties: Record<string, unknown>;\n}\nexport interface DbEdge {\n    id: string;\n    from: string;\n    to: string;\n    type: string;\n    properties: Record<string, unknown>;\n}\n/** One atomic commit. Deletes apply before upserts; deleting a node deletes its edges. */\nexport interface DbBatch {\n    deleteEdges?: Array<string>;\n    deleteNodes?: Array<string>;\n    upsertNodes?: Array<DbNode>;\n    upsertEdges?: Array<DbEdge>;\n}\nexport interface DbNodeFilter {\n    label?: string;\n    properties?: Record<string, unknown>;\n    prefix?: {\n        property: string;\n        value: string;\n    };\n    limit?: number;\n}\nexport interface DbNeighborFilter {\n    nodeId: string;\n    direction: 'out' | 'in';\n    edgeType?: string;\n}\nexport interface DbNeighbor {\n    edgeId: string;\n    nodeId: string;\n    type: string;\n    properties: Record<string, unknown>;\n}\nexport interface DbQueryResult {\n    columns: Array<string>;\n    rows: Array<Array<unknown>>;\n    truncated: boolean;\n}\n/** A read a subscription keeps current. */\nexport type DbSubscription = {\n    method: 'inspect';\n} | {\n    method: 'getNode' | 'getEdge';\n    args: {\n        id: string;\n    };\n} | {\n    method: 'queryNodes';\n    args?: DbNodeFilter;\n} | {\n    method: 'neighbors';\n    args: DbNeighborFilter;\n} | {\n    method: 'query';\n    args: {\n        cypher: string;\n        params?: Record<string, unknown>;\n        rowCap?: number;\n    };\n};\n/** A failed database call. `code` is stable, such as `read_only`. */\nexport declare class DbError extends Error {\n    readonly code: string;\n    constructor({ code, message }: DbFailure);\n}\n/** The databases of one sandbox document, and the subscriptions it holds on them. */\nexport declare class Databases {\n    private readonly rpc;\n    private readonly listeners;\n    private nextId;\n    constructor(rpc: Rpc);\n    /** A subscribed read's result arrived from the page. */\n    changed(id: number, outcome: DbOutcome): void;\n    open(name: string): {\n        name: string;\n        inspect: () => Promise<{\n            writable: boolean;\n            version: number;\n            nodes: number;\n            edges: number;\n            /** Past versions kept, the current one included, and when the oldest was made. */\n            history: {\n                commits: number;\n                oldestMs: number;\n            } | null;\n            /**\n             * Days of past versions this App's declaration asks for; older ones\n             * go when the database is compacted. Its own window, whatever the\n             * handle it is read through was opened with.\n             */\n            historyDays: number;\n        }>;\n        mutate: (batch: DbBatch) => Promise<{\n            txnId: number;\n            graphVersion: number;\n        }>;\n        getNode: (id: string) => Promise<DbNode | null>;\n        getEdge: (id: string) => Promise<DbEdge | null>;\n        queryNodes: (filter?: DbNodeFilter) => Promise<Array<DbNode>>;\n        neighbors: (filter: DbNeighborFilter) => Promise<Array<DbNeighbor>>;\n        /** One read-only Cypher query with bound parameters. Writes go through `mutate`. */\n        query: (cypher: string, params?: Record<string, unknown>, rowCap?: number) => Promise<DbQueryResult>;\n        /**\n         * Keeps a read current: `next` gets its result now and again after any\n         * commit that changes it, from this frame or another view of the App.\n         * Returns the function that stops it.\n         */\n        subscribe: <TValue = unknown>(read: DbSubscription, next: (value: TValue) => void, error?: (error: DbError) => void) => (() => void);\n    };\n}\nexport type AppDatabase = ReturnType<Databases['open']>;\n",
  "display.d.ts": "import type { Display } from './cell';\nimport type { PageAttributes } from './protocol';\n/** Shows displayed values in `container`, each in its own element. */\nexport declare function createDisplay(container: HTMLElement): Display;\n/**\n * The page as static HTML: its style elements and a copy of its body, with\n * form state written into attributes (it lives in properties), canvases as\n * images, and no scripts. The page sanitizes it again before showing it.\n * Pictures of canvases are most of a large copy: past MAX_SNAPSHOT they are\n * left out, blank at their size, until the rest fits: first a canvas hidden\n * from assistive technology (decoration, such as glass over a scene), then\n * the largest.\n */\nexport declare function snapshotHtml(): string;\n/**\n * The page as it is now: a snapshot and its outline, or null when the copy is\n * too large to send. The outline is read from the live page, which knows what\n * a copy cannot: what is hidden, what a field holds, what is checked.\n */\nexport declare function lookNow(): {\n    html: string;\n    outline: string;\n    page: PageAttributes;\n} | null;\n/**\n * What the root and the body carry that CSS reads. Left empty when it is more\n * than a page takes, so the copy is still sent.\n */\nexport declare function pageAttributes(): PageAttributes;\n/**\n * Calls `report` with a snapshot of the page once it settles after a change,\n * for the page to show where a live frame would cost too much (a canvas card\n * far out).\n */\nexport declare function observeSnapshots(report: (html: string, outline: string) => void): void;\n/**\n * Calls `report` with the document's height whenever it changes. The page's\n * box height keeps fractions, where scrollHeight rounds 186.4px down to 186\n * and the frame would scroll for the rest. scrollHeight never reads less than\n * the frame either, so a page that got shorter would keep its old height; it\n * counts only when the page overflows its box.\n *\n * A page laid out by its viewport (100vh, or height: 100% down from the root)\n * has no height of its own, and `fills` says so: the page then gives it one.\n * Such a page either exactly fills the frame it loaded in, or outgrows every\n * frame it is given (62vh + 38vh under a caption is always the caption\n * taller), so it is known by growing when nothing but its frame changed.\n * Its root and body do not resize as its content arrives, so content changes\n * are measured too.\n *\n * A page that exactly fills its frame goes on being measured: laid out by its\n * viewport, it is as tall as any frame the host gives it, so resizing the\n * frame changes nothing it reports. A page that measures any other height\n * only happened to fit its first frame, and goes back to its content height.\n */\nexport declare function observeHeight(report: (height: number, fills?: boolean) => void): void;\n/**\n * Marks the cell a selection names, and only that one, so the highlight shows\n * what the page will refer to. A selection outside every cell marks none.\n */\nexport declare function markSelectedCell(cell: Element | null | undefined): void;\n",
  "index.d.ts": "import type { TheoremApp } from './app-bridge'\n\ndeclare global {\n  /** The App's bridge to Theorem: its declared files, state, databases and runs. */\n  const theorem: TheoremApp\n  interface Window {\n    theorem: TheoremApp\n  }\n}\n\nexport {}\n",
  "outline.d.ts": "/** The most lines an outline holds; the rest are counted. */\nexport declare const MAX_OUTLINE_LINES = 400;\n/**\n * The page under `root` as a list of what is on it, one thing a line, indented\n * under what holds it:\n *\n *     - heading \"Shopping list\" [level=1]\n *     - textbox \"New item\": \"\"\n *     - button \"Add\" [disabled] [source=main.tsx:12:7]\n *\n * A `canvas` is listed and not read: what is drawn on one has no parts.\n */\nexport declare function outlineOf(root: Element): string;\n",
